
// ═══ TOKEN HELPERS ═══
// Extract access_token and refresh_token from various API response shapes.
// Supports: access_token | accessToken | token | jwt  at root or inside .data
//           refresh_token | refreshToken at root or inside .data
function _extractTokens(obj) {
  if (!obj || typeof obj !== 'object') return { at: null, rt: null };
  // Check root level first
  let at = obj.access_token || obj.accessToken || obj.token || obj.jwt || null;
  let rt = obj.refresh_token || obj.refreshToken || null;
  // Check .data nesting
  const d = obj.data;
  if (d && typeof d === 'object') {
    if (!at) at = d.access_token || d.accessToken || d.token || d.jwt || null;
    if (!rt) rt = d.refresh_token || d.refreshToken || null;
  }
  return { at, rt };
}

// ═══ LOGIN ═══
async function doLogin() {
  const btn = document.getElementById('login-btn');
  const user = document.getElementById('inp-user').value.trim();
  const pass = document.getElementById('inp-pass').value;
  const errEl = document.getElementById('login-err');
  errEl.style.display = 'none';
  btn.disabled = true; btn.textContent = 'Connecting to Wise…';
  try {
    // Use IAM exchange-token via proxy — issues a JWT that Wise REST also accepts.
    const r = await fetch(API.passwordGrant, {
      method: 'POST',
      headers: {'Content-Type':'application/json', 'Accept':'application/json'},
      body: JSON.stringify({username: user, password: pass})
    });
    const d = await r.json();
    const tk = _extractTokens(d);
    if (tk.at) {
      WISE_TOKEN = tk.at;
      try { localStorage.setItem('wise_token', WISE_TOKEN); } catch(_) {}
      if (tk.rt) {
        try { localStorage.setItem('wise_refresh_token', tk.rt); } catch(_) {}
      }
      document.getElementById('wms-user').textContent = user;
      showDash();
    } else {
      const errMsg = (d && (d.msg || d.error || d.error_description)) || 'Login failed — check your username and password.';
      errEl.textContent = errMsg;
      errEl.style.display = 'block';
      btn.disabled = false; btn.textContent = 'Sign In to WMS';
    }
  } catch(e) {
    console.warn('login network error:', e);
    const refreshed = await refreshAccessToken();
    if (refreshed) {
      document.getElementById('wms-user').textContent = user;
      showDash();
    } else {
      errEl.textContent = 'Unable to start your WMS session. Please check your sign-in and try again.';
      errEl.style.display = 'block';
      btn.disabled = false; btn.textContent = 'Sign In to WMS';
    }
  }
}

function updateTopbarDateRange() {
  const el = document.getElementById('topbar-date-text');
  if (!el) return;
  const now = new Date(new Date().toLocaleString('en-US', {timeZone: 'America/Los_Angeles'}));
  const day = now.getDay();
  const mon = new Date(now); mon.setDate(now.getDate() - (day === 0 ? 6 : day - 1));
  const sun = new Date(mon); sun.setDate(mon.getDate() + 6);
  const fmt = (d) => d.toLocaleDateString('en-US', {month:'short', day:'numeric'});
  el.textContent = fmt(mon) + ' – ' + fmt(sun) + ', ' + sun.getFullYear();
}
updateTopbarDateRange();

async function showDash() {
  document.getElementById('login-screen').style.display = 'none';
  document.getElementById('app').style.display = 'block';
  // Show Admin Settings sidebar only for owner
  const admSb = document.getElementById('sb-admin-settings');
  if (admSb) admSb.style.display = admIsOwner() ? '' : 'none';
  initCharts();
  startSyncClock();
  updateTokenStatus();
  if (!window.__wmsTokenTimersStarted) {
    window.__wmsTokenTimersStarted = true;
    setInterval(updateTokenStatus, 60000);  // re-evaluate every minute
    // Proactively renew the token before it expires so API calls do not
    // require users to paste bearer tokens.
    setInterval(tickTokenRefresh, 60000);
  }
  // Also try once on dashboard show in case the stored token is already
  // near (or past) expiry (e.g. tab was left open overnight).
  tickTokenRefresh();
  await populateFacilitySwitcher();
  const initialActiveView = document.querySelector('.view.active');
  const initialActiveName = initialActiveView ? initialActiveView.id.replace(/^view-/, '') : 'dashboard';
  if (initialActiveName === 'robots' || initialActiveName === 'gis') showView(initialActiveName);
  else { loadDashboardLiveData(); loadDashCycleCountKpi(); }
  // Sync chrome (top bar, user menu, settings) with whoever's logged in.
  // We pull user_name from the JWT when possible so this works even if
  // localStorage was pre-seeded (no fresh form input).
  let user = (document.getElementById('inp-user') || {}).value || '';
  const payload = decodeJwt(WISE_TOKEN);
  if (!user && payload && payload.data) user = payload.data.user_name || payload.sub || '';
  if (!user) user = '—';
  const setText = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };
  setText('wms-user', user);
  setText('user-menu-name', user);
  setText('settings-display-name', user);
  updateTopbarDateRange();
  // Email isn't in the JWT — leave blank unless we already have one in
  // the DOM (e.g. previously rendered). Admins can plumb email into the
  // JWT later if they want it auto-populated here.
}

// Populate the facility <select> with all facilities the user has access to.
async function populateFacilitySwitcher() {
  const sel = document.getElementById('facility-switcher');
  if (!sel) return;
  // Restore last-chosen facility from localStorage (default: LT_F1)
  let saved = 'LT_F1';
  try { saved = localStorage.getItem('facility_id') || 'LT_F1'; } catch(_) {}
  sel.innerHTML = '';
  sel.style.maxHeight = '300px';
  // Try to load facilities from IAM JWT permissions if available
  let facList = FACILITIES;
  const payload = decodeJwt(WISE_TOKEN);
  if (payload && payload.data && payload.data.facility_ids && payload.data.facility_ids.length > 0) {
    const iamFacIds = payload.data.facility_ids;
    const merged = [...FACILITIES];
    iamFacIds.forEach(fid => {
      if (!merged.find(f => f.id === fid)) merged.push({id: fid, code: '', name: fid});
    });
    facList = merged;
  }
  facList.sort((a, b) => (a.name || a.id).localeCompare(b.name || b.id));
  facList.forEach(f => {
    const o = document.createElement('option');
    o.value = f.id;
    o.textContent = f.name + ' (' + f.id + ')';
    if (f.id === saved) o.selected = true;
    sel.appendChild(o);
  });
  // If saved facility not in list, add it
  if (!facList.find(f => f.id === saved)) {
    const o = document.createElement('option');
    o.value = saved;
    o.textContent = saved;
    o.selected = true;
    sel.insertBefore(o, sel.firstChild);
  }
  // Apply the saved selection without triggering any reload work
  const fac = facList.find(f => f.id === saved) || facList[0];
  FACILITY_ID = fac.id;
  FACILITY_NAME = fac.name || fac.id;
  setFacilityLookupLoading(fac);
  const result = await FacilityData.loadLatest(fac.id);
  if (result.stale || FACILITY_ID !== fac.id) return;
  finishFacilityLookup(fac, result);
}

function setFacilityLookupLoading(fac) {
  const sel = document.getElementById('facility-switcher');
  if (sel) sel.setAttribute('aria-busy', 'true');
  const help = document.getElementById('sched-facility-help');
  if (help) help.innerHTML = 'Facility: <strong>' + esc(fac.name || fac.id) + '</strong> · Loading warehouse lookup data…';
  [document.getElementById('cc-customer'), document.getElementById('loc-customer')].forEach(select => {
    if (select) select.innerHTML = '<option value="">Loading warehouse data…</option>';
  });
}

function finishFacilityLookup(fac, result) {
  const sel = document.getElementById('facility-switcher');
  if (sel) sel.removeAttribute('aria-busy');
  if (result && result.error) {
    console.warn('[facility-data] Cached lookup unavailable for', fac.id, result.error);
  }
  updateSchedulerFacilityHelp(fac);
  refreshFacilityCustomers();
}

function updateSchedulerFacilityHelp(fac) {
  const help = document.getElementById('sched-facility-help');
  if (!help || !fac) return;
  const customers = FACILITY_CUSTOMERS[fac.id] || [];
  const locCount = customers.reduce((s,c)=>s+(c.count||0),0);
  if (customers.length === 0) {
    help.innerHTML = 'Facility: <strong>' + esc(fac.name) + '</strong> (' + fac.id + ') · <span style="color:var(--muted-foreground)">No cached location data. Use Add Count Line to search live WMS locations.</span>';
  } else if (fac.id === 'LT_F1') {
    help.innerHTML = 'Facility: <strong>' + fac.name + '</strong> · ' + customers.length + ' customers · ' + locCount.toLocaleString() + ' locations cached · Real Wise snapshot 2026-05-27';
  } else {
    help.innerHTML = 'Facility: <strong>' + fac.name + '</strong> (' + fac.id + ') · ' + customers.length + ' customers · ' + locCount.toLocaleString() + ' rows in 500-row sample · Real Wise snapshot 2026-05-27';
  }
}

async function switchFacility(newId) {
  const selected = document.getElementById('facility-switcher');
  const selectedOption = selected && selected.options ? selected.options[selected.selectedIndex] : null;
  const fac = FACILITIES.find(f => f.id === newId) || {id:newId, name:selectedOption ? selectedOption.textContent.replace(/\s*\([^)]*\)\s*$/, '') : newId};
  FACILITY_ID = fac.id;
  FACILITY_NAME = fac.name;
  try { localStorage.setItem('facility_id', newId); } catch(_) {}

  // Cancel any in-flight load + reset preview
  CC.loadToken = (CC.loadToken || 0) + 1;
  const meta = document.getElementById('cc-cust-meta');
  if (meta) meta.innerHTML = '';
  const sync = document.getElementById('sync-lbl');
  if (sync) sync.textContent = 'just now';

  setFacilityLookupLoading(fac);
  const result = await FacilityData.loadLatest(fac.id);
  if (result.stale || FACILITY_ID !== fac.id) return;
  finishFacilityLookup(fac, result);

  // Refresh scheduler help text with this facility's stats. Target the
  // dedicated facility-help element by id — NOT querySelector('.scheduler-help'),
  // which matched the first of 14 help blocks (the generic instructions) and
  // left the real "Facility: Valley View Warehouse" line stale in every facility.
  // Rebuild the counter list after the selected facility's cached lookup is ready.
  populateCounterDatalist();

  // Re-load whichever facility-scoped view is currently open so its data
  // reflects the newly selected facility. Without this, WMS data can stay stale
  // until the user navigates away and back.
  const activeView = document.querySelector('.view.active');
  const activeName = activeView ? activeView.id.replace(/^view-/, '') : '';
  if (activeName === 'dashboard') {
    loadDashboardLiveData();
    loadDashCycleCountKpi();
  } else if (activeName === 'cycle') {
    loadCycleCountView();
  } else if (activeName === 'robots') {
    refreshOntologyStatus();
    loadRobotKpisFromOntology();
  } else if (activeName === 'gis') {
    await initGisView({facilityChanged:true});
  } else if (activeName === 'scheduler') {
    loadExistingSchedules();
    renderTasksPanel();
  } else if (activeName === 'inventory') {
    // Inventory is now live and facility-scoped; refresh it immediately when
    // the warehouse changes so the table never shows another facility's data.
    loadLiveInventory();
  }

  setLiveStatus(false);
}

// Rebuild the Customer <select> on the scheduler form + the modal mirror,
// using FACILITY_CUSTOMERS[FACILITY_ID].
function refreshFacilityCustomers() {
  const customers = FACILITY_CUSTOMERS[FACILITY_ID] || [];
  if (customers.length > 0) {
    const sorted = [...customers].sort((a, b) => (a.name || '').localeCompare(b.name || ''));
    const opts = sorted.map(c => ({id: c.id, name: c.name + (c.count ? '  (' + c.count.toLocaleString() + ' locs)' : '')}));
    fillSelect(document.getElementById('cc-customer'), opts);
    fillSelect(document.getElementById('loc-customer'), opts);
    const cust = document.getElementById('cc-customer');
    if (cust) cust.value = '';
    syncAddLineEnabled();
    return;
  }
  // No static customers for this facility — fetch from WMS API
  fetchFacilityCustomersFromAPI();
}

async function fetchFacilityCustomersFromAPI() {
  const cust = document.getElementById('cc-customer');
  const locCust = document.getElementById('loc-customer');
  if (cust) cust.innerHTML = '<option value="">Loading customers…</option>';

  let allCustomers = [];
  let page = 1;
  const pageSize = 200;
  let hasMore = true;

  while (hasMore) {
    const resp = await safeFetch(WMS_BASE + '/api/mdm/customer/search-by-paging', {
      method: 'POST',
      headers: {'Content-Type':'application/json'},
      body: JSON.stringify({currentPage: page, pageSize: pageSize}),
    });

    if (!resp || resp._needsAuth || resp.success === false) {
      if (page === 1) console.warn('[customers] API failed for facility', FACILITY_ID);
      break;
    }

    const d = resp.data || resp;
    const rows = (d.list || d.records || []).map(c => ({
      id: c.orgId || c.id || c.customerId,
      name: c.name || c.customerName || c.orgName || c.id,
      code: c.code || c.customerCode || '',
      count: 0,
    }));

    allCustomers = allCustomers.concat(rows);
    const total = d.totalCount || d.total || 0;
    if (rows.length < pageSize || allCustomers.length >= total) hasMore = false;
    else page++;
    // Safety cap to avoid infinite loops
    if (page > 10) break;
  }

  if (allCustomers.length === 0) {
    console.warn('[customers] API returned 0 customers for facility', FACILITY_ID);
  } else {
    console.log('[customers] Loaded', allCustomers.length, 'customers for', FACILITY_ID);
  }

  // Cache for this session
  if (allCustomers.length > 0) FACILITY_CUSTOMERS[FACILITY_ID] = allCustomers;

  // Sort alphabetically by name for business users
  const sorted = [...allCustomers].sort((a, b) => (a.name || '').localeCompare(b.name || ''));
  const opts = sorted.map(c => ({id: c.id, name: c.name + (c.code ? ' (' + c.code + ')' : '')}));
  fillSelect(cust, opts);
  fillSelect(locCust, opts);
  if (cust) cust.value = '';
  syncAddLineEnabled();

  if (allCustomers.length === 0) {
    if (cust) cust.innerHTML = '<option value="">Customer options could not be loaded for this warehouse. Please retry or contact an administrator.</option>';
  }
}

// ═══ VIEW ROUTING ═══
