window.addEventListener('item-theme-change', refreshChartTheme);

function updateLineChart(days) {
  // Keep the dashboard live: if WMS inventory has loaded, the chart shows live
  // available quantity by customer. Static fallback only appears before login/data load.
  if (DASH_STATE && DASH_STATE.inventoryRows && DASH_STATE.inventoryRows.length) {
    dashRenderInventory(DASH_STATE.inventoryRows, DASH_STATE.customerInventory ? new Set(DASH_STATE.inventoryRows.map(r => r.customerId).filter(Boolean)).size : 0);
    return;
  }
  const d = days==='7' ? DATA_7 : DATA_30;
  lineChart.data.labels = d.labels;
  lineChart.data.datasets[0].data = d.values;
  lineChart.update();
}

// ═══ AI INSIGHT ═══
async function loadInsight(live) {
  const el = document.getElementById('ai-msg');
  if (!el) return;
  el.textContent = 'Analyzing live WMS data…';
  el.classList.add('loading');
  const invRows = (live && live.inventoryRows) || (DASH_STATE && DASH_STATE.inventoryRows) || [];
  const tickets = (live && live.tickets) || (DASH_STATE && DASH_STATE.tickets) || [];
  const low = invRows.filter(r => dashAvail(r) > 0 && dashAvail(r) <= 10).length;
  const out = invRows.filter(r => dashAvail(r) <= 0).length;
  const completed = tickets.filter(t => dashTicketStatus(t) === 'completed').length;
  const open = tickets.length - completed;
  try {
    const prompt = 'You are a WMS warehouse analyst for UNIS. Write exactly ONE sharp, actionable sentence for the warehouse manager based only on these live dashboard metrics for facility ' + (FACILITY_NAME || FACILITY_ID) + ': inventory rows sampled ' + invRows.length + ', low-stock rows ' + low + ', out-of-stock rows ' + out + ', cycle count tickets ' + tickets.length + ', completed tickets ' + completed + ', open/in-progress tickets ' + open + '. Do not mention demo data.';
    const insight = await window.cowork.askClaude(prompt, []);
    el.textContent = insight;
  } catch(e) {
    el.textContent = invRows.length || tickets.length ? ('Live WMS loaded: ' + out + ' out-of-stock rows, ' + low + ' low-stock rows, and ' + open + ' open cycle count tickets need review.') : 'Sign in or refresh to load live WMS inventory and cycle count metrics.';
  }
  el.classList.remove('loading');
}

// ═══ SYNC CLOCK ═══
function startSyncClock() {
  let s = 0;
  const el = document.getElementById('sync-lbl');
  setInterval(()=>{
    s++;
    el.textContent = s < 60 ? s+'s ago' : s < 3600 ? Math.floor(s/60)+'m ago' : Math.floor(s/3600)+'h ago';
  },1000);
}

async function refreshAll() {
  document.getElementById('sync-lbl').textContent = 'just now';
  await tickTokenRefresh();
  loadInsight();
  updateTokenStatus();
}

// ═══ USER MENU / LOGOUT ═══
function toggleUserMenu(e) {
  if (e) e.stopPropagation();
  const m = document.getElementById('user-menu');
  if (!m) return;
  const isOpen = m.classList.toggle('open');
  if (isOpen) {
    // Set up an outside-click handler to close it
    setTimeout(() => {
      document.addEventListener('click', closeUserMenu, {once: true});
    }, 0);
  }
}
function closeUserMenu() {
  const m = document.getElementById('user-menu');
  if (m) m.classList.remove('open');
}
function doLogout() {
  closeUserMenu();
  // Clear stored credentials and per-user state
  try {
    localStorage.removeItem('wise_token');
    localStorage.removeItem('wise_refresh_token');
    localStorage.removeItem('facility_id');
  } catch(_) {}
  WISE_TOKEN = null;
  // Reset internal scheduler state so a fresh session starts clean
  CC.countLines = [];
  CC.ignoreFields = new Set(['EXPIRATION_DATE','MFG_DATE','LOT_NO','SN']);
  CC.schedulerInitDone = false;
  CC.loadToken = (CC.loadToken || 0) + 1;
  // Hide the app, show the login screen, clear password
  document.getElementById('app').style.display = 'none';
  document.getElementById('login-screen').style.display = 'flex';
  const pw = document.getElementById('inp-pass');
  if (pw) pw.value = '';
  const btn = document.getElementById('login-btn');
  if (btn) { btn.disabled = false; btn.textContent = 'Sign In to WMS'; }
  const err = document.getElementById('login-err');
  if (err) err.style.display = 'none';
}

// Decode a JWT's payload (no signature verification — display only).
function decodeJwt(tok) {
  try {
    const parts = tok.split('.');
    if (parts.length < 2) return null;
    let mid = parts[1].replace(/-/g,'+').replace(/_/g,'/');
    while (mid.length % 4) mid += '=';
    return JSON.parse(atob(mid));
  } catch(e) { return null; }
}

function hasStoredRefreshToken() {
  try { return !!localStorage.getItem('wise_refresh_token'); } catch(_) { return false; }
}

function tokenMsLeft(tok) {
  const payload = decodeJwt(tok);
  if (!payload || !payload.exp) return -Infinity;
  return (payload.exp * 1000) - Date.now();
}

function tokenNeedsRefresh(tok, thresholdMs) {
  thresholdMs = thresholdMs == null ? 120000 : thresholdMs;
  return tokenMsLeft(tok) < thresholdMs;
}

function updateTokenStatus() {
  const el = document.getElementById('token-status');
  if (!el) return;
  const payload = decodeJwt(WISE_TOKEN);
  if (!payload || !payload.exp) {
    if (hasStoredRefreshToken()) el.innerHTML = '<span style="color:var(--chart-4)">· session ready</span>';
    else el.innerHTML = '<span style="color:var(--destructive)">· reconnect required</span>';
    return;
  }
  const msLeft = (payload.exp * 1000) - Date.now();
  if (msLeft <= 0) {
    el.innerHTML = hasStoredRefreshToken()
      ? '<span style="color:var(--chart-4)">· refreshing session</span>'
      : '<span style="color:var(--destructive)">· reconnect required</span>';
  } else {
    // Keep the status business-facing; the app refreshes automatically in the background.
    el.innerHTML = '<span style="color:var(--chart-3)">· session active</span>';
  }
}

// Silent token renewal using the refresh_token stored at login. Returns
// true on success (WISE_TOKEN is updated and persisted), false on any
// failure. Safe to call concurrently — duplicate calls are coalesced
// onto the single in-flight refresh promise.
let _refreshInFlight = null;
async function refreshAccessToken() {
  if (_refreshInFlight) return _refreshInFlight;
  _refreshInFlight = (async () => {
    let rt = null;
    try { rt = localStorage.getItem('wise_refresh_token'); } catch(_) {}
    if (!rt) { updateTokenStatus(); return false; }
    try {
      // Primary contract is camelCase refreshToken. A snake_case retry is kept
      // for compatibility with older IAM responses without exposing any secret.
      const payloads = [{refreshToken: rt}, {refresh_token: rt}];
      for (const payload of payloads) {
        const r = await fetch(API.refreshAuth, {
          method: 'POST',
          headers: {'Content-Type':'application/json', 'Accept':'application/json'},
          body: JSON.stringify(payload)
        });
        let d = null;
        try { d = await r.json(); } catch(_) {}
        const tk = _extractTokens(d);
        if (tk.at) {
          WISE_TOKEN = tk.at;
          try { localStorage.setItem('wise_token', WISE_TOKEN); } catch(_) {}
          // Some IdPs rotate the refresh_token on every renewal; persist if so.
          if (tk.rt) {
            try { localStorage.setItem('wise_refresh_token', tk.rt); } catch(_) {}
          }
          updateTokenStatus();
          console.log('refreshAccessToken: silent renewal succeeded');
          return true;
        }
        // If the server explicitly accepted the request but did not return a token,
        // do not keep retrying alternative shapes.
        if (r.ok) break;
      }
      updateTokenStatus();
      return false;
    } catch(e) {
      console.warn('refreshAccessToken: network error', e);
      updateTokenStatus();
      return false;
    }
  })();
  try { return await _refreshInFlight; }
  finally { _refreshInFlight = null; }
}

async function ensureWiseToken(force) {
  if (!force && WISE_TOKEN && !tokenNeedsRefresh(WISE_TOKEN, 120000)) return true;
  const ok = await refreshAccessToken();
  if (ok) return true;
  // If the token is still usable, allow the current request to proceed.
  return !!(WISE_TOKEN && !tokenNeedsRefresh(WISE_TOKEN, 0));
}

// Proactive renewal: invoked every minute. If the access token is within
// 2 minutes of expiry, refresh silently so no API call ever sees a 401
// from natural expiry.
async function tickTokenRefresh() {
  await ensureWiseToken(false);
}

// Reconnect: silently try refresh; if that fails, return to sign-in.
async function showReconnect() {
  closeUserMenu();
  const ok = await refreshAccessToken();
  if (ok) {
    updateTokenStatus();
    setLiveStatus(null);
    CC.liveOk = null;
    const v = document.getElementById('cc-customer');
    if (v && v.value) previewCustomerLocationCount(v.value);
    return;
  }
  // No usable refresh token — clear session and return to sign-in
  try {
    localStorage.removeItem('wise_token');
    localStorage.removeItem('wise_refresh_token');
  } catch(_) {}
  WISE_TOKEN = null;
  document.getElementById('app').style.display = 'none';
  document.getElementById('login-screen').style.display = 'flex';
  const pw = document.getElementById('inp-pass');
  if (pw) pw.value = '';
  const btn = document.getElementById('login-btn');
  if (btn) { btn.disabled = false; btn.textContent = 'Sign In to WMS'; }
  const err = document.getElementById('login-err');
  if (err) { err.style.display = 'none'; }
}

