let FACILITY_ID   = 'LT_F1';                  // current selection (Valley View)
let FACILITY_NAME = 'Valley View';
const TENANT_ID   = 'LT';
// Real Wise endpoints discovered from the bundled JS clients.
const API = {
  // Auth — Atlas password-grant returns a JWT that Wise REST also accepts.
  passwordGrant:   '/api/proxy/auth/password-grant',
  // Silent renewal — POST {refreshToken: "..."} (camelCase!) returns a new
  // access_token without re-prompting for the password.
  refreshAuth:     '/api/proxy/auth/refresh',
  // Customers (master data)
  customers:       WMS_BASE + '/api/mdm/customer/search-by-paging',
  // Locations
  locSearch:       WMS_BASE + '/api/wms-bam/wms-location/search-by-paging',
  // Cycle count endpoints — discovered in the cyclecount.item.com microservice
  // bundle (cyclecount-app/cycle-count/*). The browser proxies them through
  // unis.item.com so they share the WMS token. Verified working endpoints:
  //   POST /api/cyclecount-app/cycle-count/count-ticket             (create ticket — primary)
  //   POST /api/cyclecount-app/cycle-count/count-ticket/search-by-paging
  //   POST /api/cyclecount-app/cycle-count/schedule                 (recurrence rule)
  //   POST /api/cyclecount-app/cycle-count/plan                     (plan w/ filter + schedule)
  ccTypes:         WMS_BASE + '/api/wms/cycle-count/types',
  ccMethods:       WMS_BASE + '/api/wms/cycle-count/methods',
  ccCollectFields: WMS_BASE + '/api/wms/cycle-count/collect-fields',
  ccSchedule:      WMS_BASE + '/api/cyclecount-app/cycle-count/count-ticket',
  // Update an existing ticket:    PUT  to ${ccSchedule}/{id}
  // Cancel a ticket:              PUT  to ${ccSchedule}/{id}/cancel
  // Recurrence schedule:          POST to /api/cyclecount-app/cycle-count/schedule
  // Submit a count result:        POST to ${ccSchedule}/{ticketId}/count-task/{taskId}/count-result
  // Pull progress for a ticket:   POST to /api/cyclecount-bam/cycle-count/count-progress/latest/statistics
};
// Build the count-result POST URL for a specific ticket + task.
function ccCountResultUrl(ticketId, taskId) {
  return API.ccSchedule + '/' + encodeURIComponent(ticketId) +
         '/count-task/' + encodeURIComponent(taskId) + '/count-result';
}
const API_COUNT_PROGRESS = WMS_BASE + '/api/cyclecount-bam/cycle-count/count-progress/latest/statistics';
const API_COUNT_RESULTS = WMS_BASE + '/api/cyclecount-app/cycle-count/count-result/search-by-paging';
// Enriched count-result detail includes display fields such as locationName.
// The app count-result endpoint can return only numeric locationId/systemLocationId.
const API_COUNT_RESULTS_DETAIL = WMS_BASE + '/api/cyclecount-bam/cycle-count/count-result/detail/search-by-paging';
