const FACILITY_CUSTOMERS = FacilityData.customers;

// Per-facility, per-customer USABLE location rows in TUPLE format:
// [name, picktype_code, occ_code, type_code] — trailing empties trimmed.
// picktype: P=PIECE_PICK, C=CASE_PICK, L=PALLET_PICK, N=NONE, ''=null
// occ:      E=EMPTY, O=OCCUPIED, F=FULL, ''=null
// type:     ''=LOCATION (default), S=STAGING, K=PICK, D=DOCK, T=STATION, A=AUTOMATED_LOCATION
// status is always USABLE (rows filtered server-side). Pulled 2026-05-27.
